async function populateParserModels(){
  const p=$('#provider').value, c=cfg(), s=$('#parseModel'); s.innerHTML='';
  if(p==='custom'){
    s.appendChild(option(tt('og.fillid'))); s.options[0].disabled=true;
    $('#parseCustomModelRow').hidden=false;
    return;
  }
  $('#parseCustomModelRow').hidden=true;
  const models=[...(c.chat||[]),...(c.vision||[])];
  if(models.length){ const g=optgroup(tt('og.parser')); [...new Set(models)].forEach(m=>g.appendChild(option(m))); s.appendChild(g); }
  const requestBase=baseURL(), requestKey=cleanKey($('#key').value);
  const res=await fetchOnlineModels();
  if(p!==$('#provider').value || requestBase!==baseURL() || requestKey!==cleanKey($('#key').value)) return;
  const online=res.list.filter(m=>kindOf(m)==='chat');
  if(online.length){ const g=optgroup(tt('og.live')); [...new Set(online)].forEach(m=>g.appendChild(option(m))); s.appendChild(g); }
  const saved=localStorage.getItem('ff_parse_model_'+p);
  if(saved && [...s.options].some(o=>o.value===saved)) s.value=saved;
  liveModels.parser = res.ok ? res.list : null;
  checkModelEnabled('#parseModel','#parseModelWarn',liveModels.parser);
}

