let parserCatalogController;
function parserCatalog(){
  return parserCatalogController ||= createParserModelCatalog({
    select:$('#parseModel'),status:$('#parserCatalogStatus'),
    readConfig:()=>{
      const provider=$('#provider').value,c=cfg(),base=baseURL();
      $('#parseCustomModelRow').hidden=provider!=='custom';
      return {provider,base,key:cleanKey($('#key').value),proto:c.proto,
        defaults:[...(c.chat||[]),...(c.vision||[])],
        snapshotAllowed:provider==='nonelinear'&&base===(MAN.providers.nonelinear.base||'').replace(/\/+$/,''),
        placeholder:provider==='custom'?tt('og.fillid'):!provider?refsText('请选择服务商','Select a provider'):''};
    },
    readSaved:p=>localStorage.getItem('ff_parse_model_'+p),
    isParserModel:m=>kindOf(m)==='chat',
    onLiveModels:list=>{liveModels.parser=list;checkModelEnabled('#parseModel','#parseModelWarn',list);}
  });
}
function populateParserModels(){return parserCatalog().refresh();}
